const { query } = require('../db');
const logger = require('../utils/logger');
const { parsePositiveInt } = require('../utils/envUtils');

const WRITABLE_STATUS_CACHE_MS = Math.max(
  0,
  parsePositiveInt(process.env.WRITABLE_STATUS_CACHE_MS, 1500),
);

let writableStatusCache = null;
let writableStatusCachePromise = null;

function normalizeBaseUrl(rawValue) {
  const value = (rawValue || '').toString().trim();
  if (!value) return null;
  return value.endsWith('/') ? value.slice(0, -1) : value;
}

function sameBaseUrl(left, right) {
  const normalizedLeft = normalizeBaseUrl(left);
  const normalizedRight = normalizeBaseUrl(right);
  if (!normalizedLeft || !normalizedRight) return false;
  try {
    const leftUrl = new URL(normalizedLeft);
    const rightUrl = new URL(normalizedRight);
    const leftPort =
      leftUrl.port || (leftUrl.protocol === 'https:' ? '443' : '80');
    const rightPort =
      rightUrl.port || (rightUrl.protocol === 'https:' ? '443' : '80');
    return (
      leftUrl.protocol === rightUrl.protocol &&
      leftUrl.hostname.toLowerCase() === rightUrl.hostname.toLowerCase() &&
      leftPort === rightPort
    );
  } catch (_) {
    return normalizedLeft === normalizedRight;
  }
}

function resolveSyncPolicy() {
  const configured = (process.env.POSTGRES_PRIMARY_SYNC_MODE || 'async')
    .toString()
    .trim()
    .toLowerCase();
  return configured === 'strict' ? 'strict' : 'async';
}

function resolveFailoverState({ writable, replicationHealthy, syncProfile }) {
  if (writable) {
    return syncProfile === 'degraded' ? 'primary_fail_open' : 'primary';
  }

  if (!replicationHealthy) {
    return 'standby_disconnected';
  }

  return 'standby';
}

function resolveSwitchReason({ writable, peerApiBaseUrl, syncProfile }) {
  if (!writable && peerApiBaseUrl) {
    return 'local_not_writable_use_peer';
  }

  if (writable && syncProfile === 'degraded') {
    return 'strict_sync_temporarily_degraded';
  }

  return null;
}

function cloneWritableStatus(status) {
  return status ? { ...status } : status;
}

function cacheWritableStatus(status) {
  if (WRITABLE_STATUS_CACHE_MS <= 0) {
    return cloneWritableStatus(status);
  }

  writableStatusCache = {
    value: cloneWritableStatus(status),
    expiresAt: Date.now() + WRITABLE_STATUS_CACHE_MS,
  };
  return cloneWritableStatus(status);
}

async function resolveWritableStatus() {
  const checkedAt = new Date().toISOString();
  const nodeApiBaseUrl = normalizeBaseUrl(process.env.PUBLIC_API_URL);
  const peerApiBaseUrl = normalizeBaseUrl(process.env.PUBLIC_API_FALLBACK_URL);
  const peerIsDistinct =
    Boolean(peerApiBaseUrl) && !sameBaseUrl(peerApiBaseUrl, nodeApiBaseUrl);
  const syncPolicy = resolveSyncPolicy();

  try {
    const [{ rows: roleRows }, { rows: syncRows }] = await Promise.all([
      query('SELECT pg_is_in_recovery() AS in_recovery'),
      query(`
        SELECT
          current_setting('synchronous_commit', true) AS synchronous_commit,
          current_setting('synchronous_standby_names', true) AS synchronous_standby_names
      `),
    ]);

    const rows = roleRows;
    const inRecovery = Boolean(rows[0]?.in_recovery);

    let replicationHealthy = false;
    let streamingReplicaCount = 0;

    if (inRecovery) {
      const walReceiverResult = await query(`
        SELECT EXISTS(
          SELECT 1
          FROM pg_stat_wal_receiver
          WHERE status = 'streaming'
        ) AS wal_receiver_streaming
      `);
      replicationHealthy = Boolean(
        walReceiverResult.rows[0]?.wal_receiver_streaming,
      );
    } else {
      const replicationResult = await query(`
        SELECT COUNT(*)::int AS streaming_replica_count
        FROM pg_stat_replication
        WHERE state = 'streaming'
      `);
      streamingReplicaCount = Number(
        replicationResult.rows[0]?.streaming_replica_count || 0,
      );
      replicationHealthy = streamingReplicaCount > 0;
    }

    const writable = !inRecovery;
    const databaseRole = inRecovery ? 'standby' : 'primary';
    const syncCommit = (syncRows[0]?.synchronous_commit || '').toString();
    const syncStandbyNames = (
      syncRows[0]?.synchronous_standby_names || ''
    ).toString();

    let syncProfile = syncPolicy;
    if (databaseRole === 'standby') {
      syncProfile = 'standby';
    } else if (syncPolicy === 'strict' && !replicationHealthy) {
      syncProfile = 'degraded';
    }

    const preferredWriteBaseUrl = writable
      ? nodeApiBaseUrl
      : peerIsDistinct
        ? peerApiBaseUrl
        : null;
    const preferredReadBaseUrl = nodeApiBaseUrl || peerApiBaseUrl;
    const switchReason = resolveSwitchReason({
      writable,
      peerApiBaseUrl: peerIsDistinct ? peerApiBaseUrl : null,
      syncProfile,
    });

    return {
      checkedAt,
      healthy: true,
      writable,
      databaseRole,
      nodeApiBaseUrl,
      peerApiBaseUrl,
      preferredWriteBaseUrl,
      preferredReadBaseUrl,
      switchRecommended: !writable && peerIsDistinct,
      switchReason,
      syncPolicy,
      syncProfile,
      synchronousCommit: syncCommit,
      synchronousStandbyNames: syncStandbyNames,
      replicationHealthy,
      streamingReplicaCount,
      failoverState: resolveFailoverState({
        writable,
        replicationHealthy,
        syncProfile,
      }),
    };
  } catch (error) {
    logger.warn('backendRoleService: failed to resolve database role', {
      error: error.message,
    });

    return {
      checkedAt,
      healthy: false,
      writable: false,
      databaseRole: 'unavailable',
      nodeApiBaseUrl,
      peerApiBaseUrl,
      preferredWriteBaseUrl: peerIsDistinct ? peerApiBaseUrl : null,
      preferredReadBaseUrl: nodeApiBaseUrl || peerApiBaseUrl,
      switchRecommended: peerIsDistinct,
      switchReason: peerIsDistinct ? 'local_unreachable_use_peer' : null,
      syncPolicy,
      syncProfile: 'unavailable',
      synchronousCommit: null,
      synchronousStandbyNames: null,
      replicationHealthy: false,
      streamingReplicaCount: 0,
      failoverState: 'unknown',
      error: error.message,
    };
  }
}

async function getWritableStatus() {
  return resolveWritableStatus();
}

async function getWritableStatusCached() {
  if (WRITABLE_STATUS_CACHE_MS <= 0) {
    return getWritableStatus();
  }

  const now = Date.now();
  if (writableStatusCache?.value && writableStatusCache.expiresAt > now) {
    return cloneWritableStatus(writableStatusCache.value);
  }

  if (writableStatusCachePromise) {
    return writableStatusCachePromise;
  }

  writableStatusCachePromise = (async () => {
    try {
      const status = await getWritableStatus();
      return cacheWritableStatus(status);
    } finally {
      writableStatusCachePromise = null;
    }
  })();

  return writableStatusCachePromise;
}

async function isWritableNode() {
  const status = await getWritableStatus();
  return Boolean(status.healthy && status.writable);
}

function clearWritableStatusCache() {
  writableStatusCache = null;
  writableStatusCachePromise = null;
}

module.exports = {
  getWritableStatus,
  getWritableStatusCached,
  isWritableNode,
  clearWritableStatusCache,
};
